import{z as m,x as p,o as t,c as d,q as o,j as n,D as e,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const B=JSON.parse('{"title":"多轮对话 loss mask","description":"","frontmatter":{"title":"多轮对话 loss mask","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multiturn-loss-mask.md","filePath":"llm/multiturn-loss-mask.md","lastUpdated":1791413859000}'),E={name:"llm/multiturn-loss-mask.md"};function k(A,a,c,h,_,g){const s=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="多轮对话-loss-mask" tabindex="-1">多轮对话 loss mask <a class="header-anchor" href="#多轮对话-loss-mask" aria-label="Permalink to &quot;多轮对话 loss mask&quot;">​</a></h1><div class="epigraph"><p>response_mask 在模型自己采样的 token 上为 1，在工具观察与 padding 上为 0；策略梯度只应落在前者。</p><footer>—— verl AgentLoop 输出约定；对照 InstructGPT 只在助手轮计损失的监督实践</footer></div><p>多轮 SFT 已经规定：不要预测用户会说什么，损失打在助手轮。见 <a href="/llm/multiturn-format">多轮对话数据格式</a>。Agent RL 多了一类不是人写的 token：<strong>工具与环境的观察</strong>。它们出现在上下文里，条件着下一步动作，但不是 \\(\\pi_\\theta\\) 的输出。若把整段序列当 completion 做 PPO，模型会学着模仿检索片段、SQL 结果或编译器日志，重要性比也在不可控「动作」上计算。VeRL 的 <code>AgentLoopOutput.response_mask</code>、OpenRLHF / slime 的 postprocess 钩子、Agent Lightning 的调用级样本，都是在落实同一条契约。本篇只写 <strong>mask 的定义、与 token 级 API 的关系、以及归一化时 0/1 如何进分母</strong>。不重讲 chat template 字段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单轮 RLVR 的序列是 <code>[prompt | completion]</code>，prompt 全 0，completion 全 1，终点奖励广播到 1 的位置。多轮 ReAct 变成</p> \\[p,\\; a^{(1)},\\; o^{(1)},\\; a^{(2)},\\; o^{(2)},\\; \\ldots,\\; a^{(K)} \\]<p>其中 \\(a^{(k)}\\sim\\pi_\\theta\\)， \\(o^{(k)}\\) 由环境决定。正确的逐 token 掩码 \\(m_t\\in\\{0,1\\}\\) 满足 \\(m_t=1\\) 当且仅当位置 \\(t\\) 属于某段 \\(a^{(k)}\\)（且通常排除 padding）。策略目标是 \\(\\sum_t m_t\\cdot \\ell_t\\)，其中 \\(\\ell_t\\) 是裁剪后的 PPO/GRPO 项。把 \\(m_t\\) 在 \\(o^{(k)}\\) 上设成 1，等于声称模型「选择了」搜索引擎返回的词。</p><p><span class="marginnote">直觉类比：阅卷只应改学生的答案，不能把标准答案抄进学生卷面再一起判分。工具观察就是标准答案——它进上下文（卷面），但梯度（分数）只算在模型自己写的 token 上。mask 为 1 的位置，就是「学生亲笔」的位置。</span></p><p>实现层还有假 mask：先 decode 成文本、拼 messages、再 <code>apply_chat_template</code> 得到新 id，按角色启发式标助手为 1。启发式在工具角色名、system 注入、thinking 标签上会飘。唯一可靠的来源是生成时记下的 response id 边界。这就是 <a href="/llm/agentloop-server">AgentLoop</a> 坚持 token-in-token-out 的原因，也是 <a href="/llm/agent-lightning">Agent Lightning</a> v1.0 把 retokenization 列为训练事故的原因。</p><h3 id="助手轮不等于模型采样轮" tabindex="-1">助手轮不等于模型采样轮 <a class="header-anchor" href="#助手轮不等于模型采样轮" aria-label="Permalink to &quot;助手轮不等于模型采样轮&quot;">​</a></h3><p>SFT 里「assistant」角色可能含教师示范的工具调用文本，那是监督，mask 为 1 合理。在线 RL 里，若 harness 把上一次模型输出改写（补 JSON、截断、插入规范字段）再写回历史，改写后的 token 已经不是 \\(\\pi_{\\mathrm{old}}\\) 的动作。要么拒绝改写、用原始 id；要么把改写段标 0。静默改写却标 1，是离策略噪声，不是数据增强。</p><p><span class="marginnote">TRL 的 SFT/DPO 默认 mask 用户轮；工具观察要自己提供 completion mask。不要假设 <code>assistant</code> 字符串检测能覆盖 <code>tool</code> 角色。OpenAI 式 <code>tool</code> 消息在模板里可能被渲染成特殊 token 块，漏标就会在大块 JSON 上反传。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记序列 \\(x_{1:T}\\)，掩码 \\(m_{1:T}\\)。PPO 的 token 项 \\(\\rho_t \\hat A_t\\) 只在 \\(m_t=1\\) 累加。组内标准化的 \\(\\hat A\\) 仍可按整段轨迹的标量奖励来，但<strong>平均</strong>时要决定分母是 \\(\\sum_t m_t\\) 还是样本数。DAPO / 某些 GRPO 实现用 token 级平均，长轨迹不会仅仅因为长就占更大梯度；若再在观察上标 1，分母被工具输出灌水，真正动作的梯度被稀释。正确做法：分母只计 \\(m_t=1\\)。Harnessed 设定下一次 rollout 拆成多次 LLM 调用时，还应在 rollout 级做优势，避免调用次数变成权重，见 Lightning v1.0。</p><p>构造 mask 的推荐流程：（1）引擎返回 <code>response_ids</code>；（2）Loop 把它们追加到序列，这些位置写 1；（3）工具文本在 <strong>client 侧</strong> tokenize 成 <code>obs_ids</code>，追加并写 0；（4）下一轮 generate 的输入是当前全部 id，不再经过文本往返。Padding 与截断位置写 0。若使用 packing，文档边界两侧不能把相邻样本的观察当成当前动作。</p>',15)),(t(),n(i,null,{default:e(()=>[r(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A1%5B%22%E6%A8%A1%E5%9E%8B%20token%20a1%20%C2%B7%20mask%201%22%5D%20--%3E%20O1%5B%22%E5%B7%A5%E5%85%B7%E8%A7%82%E5%AF%9F%20o1%20%C2%B7%20mask%200%22%5D%0A%20%20O1%20--%3E%20A2%5B%22%E6%A8%A1%E5%9E%8B%20token%20a2%20%C2%B7%20mask%201%22%5D%0A%20%20A2%20--%3E%20O2%5B%22%E8%A7%82%E5%AF%9F%20o2%20%C2%B7%20mask%200%22%5D%0A%20%20O2%20--%3E%20AK%5B%22%E6%9C%80%E7%BB%88%20aK%20%C2%B7%20mask%201%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="与-kl、价值头的接口" tabindex="-1">与 KL、价值头的接口 <a class="header-anchor" href="#与-kl、价值头的接口" aria-label="Permalink to &quot;与 KL、价值头的接口&quot;">​</a></h3><p>KL 项 \\(\\log\\pi_\\theta-\\log\\pi_{\\mathrm{ref}}\\) 也只应在 \\(m_t=1\\) 上算。对观察算 KL 没有定义：参考策略并不「生成」检索结果。价值头若逐步预测，可以看含观察的状态（那是条件），但训练 \\(V\\) 的目标位置仍建议钉在动作 token 或步末，避免在工具 JSON 上学价值。GAE 沿时间回传时，观察步可以当 \\(\\gamma\\) 转移但不贡献策略项。实现若把观察也展开成「动作」时间，GAE 会把环境噪声当成策略方差。</p><p><span class="marginnote">DeepSeekMath 的 GRPO 把标准化后的 \\(\\tilde r\\) 赋给该输出的每一个 token。多轮时应读成「每一个<strong>策略</strong> token」，不是每一个物理 token。原文实验是单轮数学，迁移到工具轨迹时必须自己改赋值范围。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Mask 是在声明 <strong>可控集</strong>。策略梯度定理针对的是 \\(\\pi\\) 的支持；环境 token 来自另一个分布。形式上可把观察并入状态更新 \\(s&#39;=f(s,a,o)\\)，动作空间仍是词表上的模型输出。工程错误等于把 \\(o\\) 标成 \\(a\\)。数值上，观察段往往更长（网页、traceback），错误的 1 会主导平均损失，训练看起来在降 loss，其实在拟合噪声文本。</p><p><span class="marginnote">「可控集」就是策略真正能决定的那部分 token。模型只对「自己写出的字」负责：检索返回了什么、编译器报了什么错，都不在它的选择空间里。策略梯度定理的推导前提，正是动作被定义为策略自己采样的 token——mask 就是在代码里执行这条定义。</span></p><p><span class="marginnote">数字实例：一条轨迹模型动作 200 token、工具观察 1800 token。若观察被误标为 1，token 平均时分母从 200 变成 2000，每个动作 token 的梯度权重被稀释到约九分之一——大部分「学习量」花在了抄网页和报错日志上。</span></p>',7)),(t(),n(i,null,{default:e(()=>[r(s,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E9%94%99%E8%AF%AF%3A%20%E8%A7%82%E5%AF%9F%E6%AE%B5%E6%A0%87%20m%3D1%22%5D%20--%3E%20DEN%5B%22%E5%B9%B3%E5%9D%87%E5%88%86%E6%AF%8D%E8%A2%AB%E9%95%BF%E5%B7%A5%E5%85%B7%E8%BE%93%E5%87%BA%E7%81%8C%E6%B0%B4%22%5D%0A%20%20DEN%20--%3E%20DIL%5B%22%E7%9C%9F%E6%AD%A3%E5%8A%A8%E4%BD%9C%E7%9A%84%E6%A2%AF%E5%BA%A6%E8%A2%AB%E7%A8%80%E9%87%8A%22%5D%0A%20%20E%20--%3E%20KL%5B%22%E5%AF%B9%E8%A7%82%E5%AF%9F%E7%AE%97%20KL%20%E6%B2%A1%E6%9C%89%E5%AE%9A%E4%B9%89%22%5D%0A%20%20KL%20--%3E%20CLIP%5B%22%E9%87%8D%E8%A6%81%E6%80%A7%E6%AF%94%E4%B8%8E%20clip%20%E5%8C%BA%E9%97%B4%E5%A4%B1%E5%8E%BB%E6%84%8F%E4%B9%89%22%5D%0A%20%20DIL%20--%3E%20W%5B%22loss%20%E5%9C%A8%E9%99%8D%2C%20%E5%AE%9E%E9%99%85%E5%9C%A8%E6%8B%9F%E5%90%88%E6%A3%80%E7%B4%A2%E6%96%87%E6%9C%AC%E4%B8%8E%E6%8A%A5%E9%94%99%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>Retokenization 破坏的是「这段文本对应的 id 就是当时的 \\(a\\)」。即使角色 mask 启发式碰巧全标在 assistant 上，id 已变，则 \\(\\log\\pi\\) 与采样分布不一致，clip 区间失去意义。因此 mask 正确性以 <strong>id 身份</strong>为前提，不以角色字符串为前提。Server 级 token API、代理层记录 raw token，都是为这条前提服务。</p><h3 id="归一化的三种错误" tabindex="-1">归一化的三种错误 <a class="header-anchor" href="#归一化的三种错误" aria-label="Permalink to &quot;归一化的三种错误&quot;">​</a></h3><ol><li>按序列长度平均且观察标 1：工具越多梯度越小。</li><li>按 sample 平均而一次任务拆成很多 sample：调用越多权重越大（Lightning 指出的编码任务偏差）。</li><li>按 batch 全局 token 平均但各样本 mask 密度差数量级：密度低的任务被淹没。</li></ol><p>需要在配置里写死：token 平均只计 \\(m=1\\)，任务级权重按 rollout 或按题分组（GRPO 的 \\(G\\)）。改一处必须改日志里的 <code>grad_norm</code> 解读。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 mask 当成「少算一点算力」的优化开关。不要在可视化时只画文本高亮、不校验 id 边界。截断若从左边砍历史，必须保证剩下的前缀仍以合法 chat 状态开始，否则第一段 \\(a\\) 的条件错误。多模态观察（图像 token）同样为 0；视觉编码器是否更新是另一条损失，不要和语言模型策略项混在一个 mask 里。</p><p>没有 token 级日志时，不要开异步 rollout：错 mask 会按吞吐放大。先在同步、单条轨迹上断言 \\(\\sum m\\) 等于模型生成长度之和。</p><p><span class="marginnote">Ouyang 等 InstructGPT 的示范损失在助手续写上。verl <code>response_mask</code>：文档 agent_loop。Jiang 等 VerlTool arXiv:2509.01055 强调观察 token。He 等 arXiv:2608.17528 强调重分词与 rollout 级归一化。Shao 等 DeepSeekMath / GRPO 原文是单轮赋值，迁移需显式改写。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多轮 RL 的 loss mask：模型采样为 1，提示、工具观察、padding 为 0。</li><li>Mask 必须标在生成时的 token id 上；文本再分词会使 0/1 对准错误位置。</li><li>平均与优势的分母、分组键要与 mask 一致，否则长观察或多次调用会扭曲梯度。</li><li>出处：verl AgentLoop 约定；InstructGPT；VerlTool；Agent Lightning v1.0。</li></ul>',10))])}const P=m(E,[["render",k]]);export{B as __pageData,P as default};
